    49	otError otIp6SetEnabled(otInstance *aInstance, bool aEnabled)
    50	{
    51	    otError   error    = OT_ERROR_NONE;
    52	    Instance &instance = *static_cast<Instance *>(aInstance);
    53	
    54	#if OPENTHREAD_ENABLE_RAW_LINK_API
    55	    VerifyOrExit(!instance.Get<Mac::LinkRaw>().IsEnabled(), error = OT_ERROR_INVALID_STATE);
    56	#endif
    57	
    58	    if (aEnabled)
    59	    {
    60	        instance.Get<ThreadNetif>().Up();
    61	    }
    62	    else
    63	    {
    64	        instance.Get<ThreadNetif>().Down();
    65	    }
    66	
    67	#if OPENTHREAD_ENABLE_RAW_LINK_API
    68	exit:
    69	#endif
    70	    return error;
    71	}
