   261	otError otIp6SelectSourceAddress(otInstance *aInstance, otMessageInfo *aMessageInfo)
   262	{
   263	    otError                         error    = OT_ERROR_NONE;
   264	    Instance &                      instance = *static_cast<Instance *>(aInstance);
   265	    const Ip6::NetifUnicastAddress *netifAddr;
   266	
   267	    netifAddr = instance.Get<Ip6::Ip6>().SelectSourceAddress(*static_cast<Ip6::MessageInfo *>(aMessageInfo));
